import os
import re
import operator
import csv
from datetime import datetime
from robot.libraries.BuiltIn import BuiltIn


class TtiTraceCommon(object):
    conditions = {
        '>': operator.gt,
        '<': operator.lt,
        '<=': operator.le,
        '>=': operator.ge,
        '==': operator.eq,
        '!=': operator.ne,
    }

    def _compare_with_in(self, y, x, condition):
        conditions_in = {'not in': x not in y, 'in': x in y}
        return conditions_in[condition]

    def _compare_values_maths(self, x, y, condition):
        conditions_math = self.conditions[condition]
        return conditions_math(float(x), float(y))

    def _get_compare_method(self, condition):
        method = self._compare_values_maths
        if 'in' in condition:
            method = self._compare_with_in
        return method

    def get_file_lines_from_tti_trace_txt_file(self, tti_txt_dirpath, tti_trace_direction):
        """
        Get list of every lines from DL.txt or UL.txt and every line is a list of column values

        :param tti_txt_dirpath: path to directory where DL.txt and UL.txt are stored
        :param tti_trace_direction: string 'dl' or 'ul'
        :return: returns list of lines and every line is list of values
        """
        if tti_trace_direction.lower() in ['dl', 'downlink']:
            tti_filename = 'DL.txt'
        elif tti_trace_direction.lower() in ['ul', 'uplink']:
            tti_filename = 'UL.txt'
        else:
            raise Exception(
                'In function: get_file_lines_from_tti_trace_txt_file, argument: tti_trace_direction '
                'should have value dl or ul, got {}'.format(tti_trace_direction)
            )
        with open(os.path.join(tti_txt_dirpath, tti_filename)) as f:
            return list(csv.reader(f))

    def filter_tti_trace_by_value_in_given_column(self, tti_file_lines, column_name, value, condition):
        """
        Remove lines that not match value/values under related column - return rest

        :param tti_file_lines: is return from get_file_lines_from_tti_trace_txt_file()
        :param column_name: string - column name from TTI
        :param value: string - value or list of values under related column
        :return: list of lines and every line is list of values
        """
        compare = self._get_compare_method(condition)
        results = tti_file_lines[0:2]
        column_index = self.get_index_of_tti_column(tti_file_lines, column_name)

        for tti_file_line in tti_file_lines[2:]:
            if compare(tti_file_line[column_index], value, condition):
                results.append(tti_file_line)
        return results

    def filter_and_compare_tti_trace_value_in_given_column_with_parameter_list(
        self, tti_file_lines, column_name, value, parameter_list
    ):
        """
        Remove lines that not match value/values under related column and compare using
        specific condition with other values under different column. KW fails if comparison fails.

        :param tti_file_lines: is return from get_file_lines_from_tti_trace_txt_file()
        :param column_name: string - column name from TTI
        :param value: string - value related column
        :parameter_list :  in format e.g. ['ETtiTraceUlParUe_tbsCw1 == 0','ETtiTraceUlParUe_Modulation == QPSK',]
        :return: list of lines and every line is list of values
        """
        content_of_tti_trace_with_given_value = self.filter_tti_trace_by_value_in_given_column(
            tti_file_lines, column_name, value, condition='in'
        )
        amount_of_given_values = len(content_of_tti_trace_with_given_value)
        BuiltIn().log(
            'amount_of_given_values from tti trace pair {} == {} is {}'.format(
                column_name, value, amount_of_given_values
            )
        )
        for parameter in parameter_list:
            parameter_column_name, condition, parameter_value = parameter.split()
            if condition == '==':
                fixed_condition = 'in'
            elif condition == '!=':
                fixed_condition = 'not in'
            else:
                fixed_condition = condition
            content_of_tti_trace_for_given_parameter = self.filter_tti_trace_by_value_in_given_column(
                content_of_tti_trace_with_given_value, parameter_column_name, parameter_value, fixed_condition
            )
            BuiltIn().log(
                'amount for parameter {} = {}'.format(parameter.split(), len(content_of_tti_trace_for_given_parameter))
            )
            if amount_of_given_values != len(content_of_tti_trace_for_given_parameter):
                BuiltIn().fail('This {} does not match for {} {}'.format(parameter.split(), column_name, value))
        return content_of_tti_trace_with_given_value

    def get_index_of_tti_column(self, tti_file_lines, column_name):
        """
        Get index of column name in TTI

        :param tti_file_lines: is return from get_file_lines_from_tti_trace_txt_file()
        :param column_name: string - column name from TTI
        :return: return index of given column name
        """
        return tti_file_lines[1].index(column_name)

    def get_time_from_tti_file_line(self, tti_file_line):
        """
        Get time (under Time column) from single TTI line in format e.g. 11:57:46.885

        :param tti_file_line: single tti file line - e.g. file_lines[4] where
               file_lines is return from get_file_lines_from_tti_trace_txt_file()
        :return: string - time (under Time column) from single TTI line in format e.g. 11:57:46.885
        """
        return re.search('T(.*)Z$', tti_file_line[0]).group(1)

    def get_tti_start_time_from_tti_file_lines(self, tti_file_lines):
        """
        Get start time from TTI trace

        :param tti_file_lines: is return from get_file_lines_from_tti_trace_txt_file()
        :return: string - time in format e.g. 11:57:46.885
        """
        return re.search('T(.*)Z$', tti_file_lines[2][0]).group(1)

    def get_tti_end_time_from_tti_file_lines(self, tti_file_lines):
        """
        Get end time from TTI trace

        :param tti_file_lines: is return from get_file_lines_from_tti_trace_txt_file()
        :return: string - time in format e.g. 11:57:46.885
        """
        return re.search('T(.*)Z$', tti_file_lines[len(tti_file_lines) - 1][0]).group(1)

    def get_duration_from_tti_file_lines(self, tti_file_lines):
        """
        Get duration of TTI trace

        :param tti_file_lines: is return from get_file_lines_from_tti_trace_txt_file()
        :return: string - time in seconds in format e.g. 0.005
        """
        time_format = '%H:%M:%S.%f'
        start_time = self.get_tti_start_time_from_tti_file_lines(tti_file_lines)
        end_time = self.get_tti_end_time_from_tti_file_lines(tti_file_lines)
        time_delta = datetime.strptime(end_time, time_format) - datetime.strptime(start_time, time_format)
        return float(re.search(r'\d+:\d+:0*(\d+\.\d{3})', str(time_delta)).group(1))

    def get_values_from_columns_in_tti(self, tti_file_lines, names_of_colums):
        """
        Get all values from specified columns names in TTI trace

        :param tti_file_lines: is return from get_file_lines_from_tti_trace_txt_file()
        :param names_of_colums: list of column names - one element list is OK
        :return: return same format as get_file_lines_from_tti_trace_txt_file() but only from specified column names
        """
        column_indexes = []
        tti_column_values = []
        tti = []
        for column_name in names_of_colums:
            column_indexes.append(self.get_index_of_tti_column(tti_file_lines, column_name))
        for line in tti_file_lines[1:]:
            for index in column_indexes:
                tti.append(line[index])
            tti_column_values.append(tti)
            tti = []
        return tti_column_values
